package com.dailyxptracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(DailyXpConfig.GROUP)
public interface DailyXpConfig extends Config
{
	String GROUP = "dailyxp";

	String KEY_SKILL_FILTER = "skillFilter";
	String KEY_CUSTOM_SKILLS = "customSkills";
	String KEY_SUMMARY_PERIOD = "summaryPeriod";

	@ConfigSection(
		name = "Window",
		description = "What span of time to total over",
		position = 0
	)
	String windowSection = "window";

	@ConfigSection(
		name = "Skills",
		description = "Which skills to include in the total",
		position = 10
	)
	String skillsSection = "skills";

	@ConfigSection(
		name = "Goal",
		description = "Daily XP target",
		position = 15
	)
	String goalSection = "goal";

	@ConfigSection(
		name = "History",
		description = "Keeping totals for completed days",
		position = 25
	)
	String historySection = "history";

	@ConfigSection(
		name = "Display",
		description = "Panel and overlay options",
		position = 30
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "trackingMode",
		name = "Tracking window",
		description = "Which window of time to total XP over.<br>"
			+ "All windows are recorded at all times, so switching between them never loses data.",
		section = windowSection,
		position = 1
	)
	default TrackingMode trackingMode()
	{
		return TrackingMode.LOCAL_DAY;
	}

	@ConfigItem(
		keyName = "countOfflineGains",
		name = "Count XP gained while closed",
		description = "On login, add XP earned while the client was closed (for example on mobile) to the "
			+ "rolling 24 hour window. The exact time it was earned is unknown, so it is attributed to the "
			+ "moment it is detected.<br>"
			+ "The day windows count it regardless of this setting, attributed to the day you next log in.",
		section = windowSection,
		position = 2
	)
	default boolean countOfflineGains()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SKILL_FILTER,
		name = "Skills to include",
		description = "Which skills count toward the headline total. Choose Custom selection to pick individual "
			+ "skills from the side panel.",
		section = skillsSection,
		position = 11
	)
	default SkillFilter skillFilter()
	{
		return SkillFilter.ALL;
	}

	@ConfigItem(
		keyName = KEY_CUSTOM_SKILLS,
		name = "Custom skills",
		description = "Comma separated skill names, used when Skills to include is set to Custom selection.<br>"
			+ "Easier to set from the side panel, but editable here if you prefer.",
		section = skillsSection,
		position = 12
	)
	default String customSkills()
	{
		return "";
	}

	@ConfigItem(
		keyName = "xpGoal",
		name = "Daily XP goal",
		description = "Target XP for the selected window. Set to 0 to hide the goal bar.",
		section = goalSection,
		position = 16
	)
	default int xpGoal()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "notifyOnGoal",
		name = "Notify when reached",
		description = "Fire a notification the first time you hit the goal each day. Day windows only, "
			+ "since the rolling window has no natural reset point.",
		section = goalSection,
		position = 17
	)
	default boolean notifyOnGoal()
	{
		return true;
	}

	@ConfigItem(
		keyName = "countOfflineTowardGoal",
		name = "Offline XP counts toward goal",
		description = "Count XP earned while the client was closed toward your daily goal.<br>"
			+ "Off by default, so XP earned before you logged in does not fill the bar before you "
			+ "start training. Turn it on if you play mostly on mobile.",
		section = goalSection,
		position = 18
	)
	default boolean countOfflineTowardGoal()
	{
		return false;
	}

	@ConfigItem(
		keyName = "historyDays",
		name = "Days of history to keep",
		description = "How many days with recorded XP to archive. Days with no XP are not stored, "
			+ "so keeping 30 can span more than 30 calendar days if you play intermittently.<br>"
			+ "Set to 0 to keep no history, which deletes anything already archived. To hide the "
			+ "list without deleting it, use the toggle below.<br>"
			+ "History records every skill, so changing your skill selection re-totals past days "
			+ "rather than blanking them.",
		section = historySection,
		position = 26
	)
	default int historyDays()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "showHistory",
		name = "Show past days in panel",
		description = "List completed days underneath the current total.",
		section = historySection,
		position = 27
	)
	default boolean showHistory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showChart",
		name = "Show history chart",
		description = "Draw the past 14 days as a bar chart above the list.<br>"
			+ "Days with no XP recorded appear as flat grey bars.",
		section = historySection,
		position = 28
	)
	default boolean showChart()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showMeanLine",
		name = "Show average line",
		description = "Draw a dashed grey line across the chart at your average XP per day.<br>"
			+ "Averaged across every day in the chart, including days with no XP, so it matches "
			+ "the per-day figure in the period summary when Last 14 days is selected.",
		section = historySection,
		position = 29
	)
	default boolean showMeanLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SUMMARY_PERIOD,
		name = "Summary period",
		description = "Set from the dropdown in the side panel.",
		section = historySection,
		position = 30,
		hidden = true
	)
	default String summaryPeriod()
	{
		return "7";
	}

	@ConfigItem(
		keyName = "showPeriodSummary",
		name = "Show period summary",
		description = "Show the box totalling your XP across a chosen period of past days.<br>"
			+ "The average is per calendar day, so days with no XP lower it.",
		section = historySection,
		position = 31
	)
	default boolean showPeriodSummary()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideUntrained",
		name = "Hide untrained skills",
		description = "Hide selected skills with no XP gained in the current window from the side panel.",
		section = displaySection,
		position = 21
	)
	default boolean hideUntrained()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverallWhenFiltered",
		name = "Show overall alongside",
		description = "When a subset of skills is selected, also show the total across all skills.",
		section = displaySection,
		position = 22
	)
	default boolean showOverallWhenFiltered()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show a small total on the game screen.",
		section = displaySection,
		position = 23
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlaySkillCount",
		name = "Overlay skill rows",
		description = "How many of your top selected skills to list on the overlay. Set to 0 for the total only.",
		section = displaySection,
		position = 24
	)
	default int overlaySkillCount()
	{
		return 3;
	}
}

package com.dailyxptracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

class DailyXpOverlay extends OverlayPanel
{
	private final DailyXpConfig config;

	/** Written from the client thread, read from the EDT during render. */
	private volatile XpSnapshot snapshot;

	@Inject
	DailyXpOverlay(DailyXpPlugin plugin, DailyXpConfig config)
	{
		super(plugin);
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		getMenuEntries().add(new OverlayMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Daily XP overlay"));
	}

	void setSnapshot(XpSnapshot snapshot)
	{
		this.snapshot = snapshot;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		XpSnapshot current = snapshot;
		if (!config.showOverlay() || current == null || current.getTotal() <= 0)
		{
			return null;
		}

		panelComponent.setPreferredSize(new Dimension(140, 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(current.getMode().getShortLabel())
			.color(Color.WHITE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Total")
			.right(QuantityFormatter.quantityToRSDecimalStack(clampToInt(current.getTotal())))
			.build());

		int rows = Math.max(0, config.overlaySkillCount());
		int added = 0;
		for (Map.Entry<String, Integer> entry : current.getGains().entrySet())
		{
			if (added >= rows)
			{
				break;
			}

			panelComponent.getChildren().add(LineComponent.builder()
				.left(Skills.display(entry.getKey()))
				.right(QuantityFormatter.quantityToRSDecimalStack(entry.getValue()))
				.build());
			added++;
		}

		return super.render(graphics);
	}

	private static int clampToInt(long value)
	{
		return (int) Math.min(value, Integer.MAX_VALUE);
	}
}

package com.dailyxptracker;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.LocalDate;
import java.time.Duration;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.QuantityFormatter;
import java.awt.Color;
import java.awt.FlowLayout;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import javax.swing.JComboBox;
import java.time.ZoneOffset;
import javax.swing.JComponent;

class DailyXpPanel extends PluginPanel
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("h:mm a");
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM");
	private static final DateTimeFormatter WEEKDAY = DateTimeFormatter.ofPattern("EEEE");

	private final SkillIconManager skillIconManager;
	private final Consumer<Set<String>> onSelectionChanged;

	private final JLabel modeLabel = new JLabel();
	private final JLabel totalLabel = new JLabel();
	private final JLabel windowLabel = new JLabel();
	private final JLabel overallLabel = new JLabel();
	private final JLabel levelsLabel = new JLabel();
	private final JLabel offlineLabel = new WideLabel();
	private final GoalBar goalBar = new GoalBar();
	private final HistoryChart chart = new HistoryChart();
	private final JLabel chartTitle = new WideLabel();
	private final JPanel legend = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
	private final JLabel meanKey = new JLabel("\u2504 average");
	private final JLabel goalKey = new JLabel("\u2501 goal");

	private final JPanel summaryPanel = new WidePanel();
	private final JComboBox<PeriodOption> periodCombo = new JComboBox<>();
	private final JLabel summaryTotal = new WideLabel();
	private final JLabel summaryDetail = new WideLabel();
	private final JLabel summaryDays = new WideLabel();

	private final Consumer<String> onPeriodChanged;

	/** Guards against option rebuilds firing the user-change callback. */
	private boolean syncingPeriod;

	private final JPanel skillList = new JPanel(new GridLayout(0, 1, 0, 3));
	private final JLabel emptyLabel = new JLabel("No XP gained yet.");

	private final JPanel historySection = new WidePanel();
	private final JPanel historyList = new JPanel(new GridLayout(0, 1, 0, 2));
	private final JLabel historyTitle = new WideLabel();

	private final JPanel pickerBody = new JPanel();
	private final JButton pickerToggle = new JButton("Choose skills");
	private final Map<String, JCheckBox> checkBoxes = new LinkedHashMap<>();

	/** Guards against the programmatic sync in update() firing user-change callbacks. */
	private boolean syncing;

	DailyXpPanel(SkillIconManager skillIconManager, Consumer<Set<String>> onSelectionChanged,
		Consumer<String> onPeriodChanged, Runnable onReset)
	{
		this.skillIconManager = skillIconManager;
		this.onSelectionChanged = onSelectionChanged;
		this.onPeriodChanged = onPeriodChanged;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel centre = new JPanel();
		centre.setLayout(new BoxLayout(centre, BoxLayout.Y_AXIS));
		centre.setBackground(ColorScheme.DARK_GRAY_COLOR);
		centre.add(buildPicker());
		centre.add(javax.swing.Box.createVerticalStrut(8));
		skillList.setAlignmentX(Component.LEFT_ALIGNMENT);
		centre.add(skillList);
		centre.add(javax.swing.Box.createVerticalStrut(10));
		centre.add(buildHistorySection());

		JButton reset = new JButton("Reset counter");
		reset.setFocusPainted(false);
		reset.setToolTipText("Clears the current windows and starts counting again from now. Archived days are kept.");
		reset.addActionListener(e -> onReset.run());

		add(buildHeader(), BorderLayout.NORTH);
		add(centre, BorderLayout.CENTER);
		add(reset, BorderLayout.SOUTH);
	}

	private JPanel buildHeader()
	{
		modeLabel.setFont(FontManager.getRunescapeSmallFont());
		modeLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		modeLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		totalLabel.setFont(FontManager.getRunescapeFont().deriveFont(Font.BOLD, 22f));
		totalLabel.setForeground(ColorScheme.BRAND_ORANGE);
		totalLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		totalLabel.setText("0");

		windowLabel.setFont(FontManager.getRunescapeSmallFont());
		windowLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		windowLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		overallLabel.setFont(FontManager.getRunescapeSmallFont());
		overallLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		overallLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		levelsLabel.setFont(FontManager.getRunescapeSmallFont());
		levelsLabel.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
		levelsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		levelsLabel.setVisible(false);

		offlineLabel.setFont(FontManager.getRunescapeSmallFont());
		offlineLabel.setForeground(ColorScheme.BRAND_ORANGE);
		offlineLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		offlineLabel.setVisible(false);

		goalBar.setAlignmentX(Component.LEFT_ALIGNMENT);
		goalBar.setVisible(false);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		header.add(modeLabel);
		header.add(totalLabel);
		header.add(goalBar);
		header.add(windowLabel);
		header.add(levelsLabel);
		header.add(offlineLabel);
		header.add(overallLabel);
		return header;
	}

	/**
	 * A collapsible checkbox list. Ticking a box writes the whole selection back through the
	 * callback, which persists it to config; config then flows back in through update().
	 */
	private JPanel buildPicker()
	{
		pickerToggle.setFocusPainted(false);
		pickerToggle.addActionListener(e ->
		{
			pickerBody.setVisible(!pickerBody.isVisible());
			pickerToggle.setText(pickerBody.isVisible() ? "Hide skills" : "Choose skills");
			revalidate();
			repaint();
		});

		JPanel presets = new JPanel(new GridLayout(1, 0, 4, 0));
		presets.setBackground(ColorScheme.DARK_GRAY_COLOR);
		presets.add(presetButton("All", new LinkedHashSet<>(Skills.all())));
		presets.add(presetButton("Combat", Skills.resolve(SkillFilter.COMBAT, "")));
		presets.add(presetButton("None", new LinkedHashSet<>()));

		JPanel grid = new JPanel(new GridLayout(0, 2, 4, 0));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (String skill : Skills.all())
		{
			JCheckBox box = new JCheckBox(Skills.display(skill));
			box.setFont(FontManager.getRunescapeSmallFont());
			box.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			box.setBackground(ColorScheme.DARK_GRAY_COLOR);
			box.setFocusPainted(false);
			box.addActionListener(e -> emitSelection());
			checkBoxes.put(skill, box);
			grid.add(box);
		}

		pickerBody.setLayout(new BoxLayout(pickerBody, BoxLayout.Y_AXIS));
		pickerBody.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pickerBody.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		pickerBody.add(presets);
		pickerBody.add(javax.swing.Box.createVerticalStrut(4));
		pickerBody.add(grid);
		pickerBody.setVisible(false);

		JPanel picker = new JPanel(new BorderLayout());
		picker.setBackground(ColorScheme.DARK_GRAY_COLOR);
		picker.add(pickerToggle, BorderLayout.NORTH);
		picker.add(pickerBody, BorderLayout.CENTER);
		picker.setAlignmentX(Component.LEFT_ALIGNMENT);
		return picker;
	}

	private JPanel buildHistorySection()
	{
		chartTitle.setFont(FontManager.getRunescapeSmallFont());
		chartTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		chartTitle.setBorder(BorderFactory.createEmptyBorder(0, 2, 4, 0));
		stretch(chartTitle);

		chart.setAlignmentX(Component.LEFT_ALIGNMENT);

		meanKey.setFont(FontManager.getRunescapeSmallFont());
		meanKey.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		meanKey.setToolTipText("Your average per day across the chart, counting days with no XP as zero");

		goalKey.setFont(FontManager.getRunescapeSmallFont());
		goalKey.setForeground(Color.WHITE);
		goalKey.setToolTipText("Your daily XP goal");

		legend.setBackground(ColorScheme.DARK_GRAY_COLOR);
		legend.setAlignmentX(Component.LEFT_ALIGNMENT);
		legend.add(meanKey);
		legend.add(goalKey);

		historyTitle.setFont(FontManager.getRunescapeSmallFont());
		historyTitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		historyTitle.setBorder(BorderFactory.createEmptyBorder(8, 2, 4, 0));
		stretch(historyTitle);

		historyList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyList.setAlignmentX(Component.LEFT_ALIGNMENT);

		historySection.setLayout(new BoxLayout(historySection, BoxLayout.Y_AXIS));
		historySection.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historySection.setAlignmentX(Component.LEFT_ALIGNMENT);
		historySection.add(chartTitle);
		historySection.add(chart);
		historySection.add(legend);
		historySection.add(javax.swing.Box.createVerticalStrut(8));
		historySection.add(buildSummary());
		historySection.add(historyTitle);
		historySection.add(historyList);
		historySection.setVisible(false);
		return historySection;
	}

	private JPanel buildSummary()
	{
		periodCombo.setFont(FontManager.getRunescapeSmallFont());
		periodCombo.setFocusable(false);
		periodCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, periodCombo.getPreferredSize().height));
		periodCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
		periodCombo.addActionListener(e ->
		{
			if (syncingPeriod)
			{
				return;
			}

			PeriodOption selected = (PeriodOption) periodCombo.getSelectedItem();
			if (selected != null)
			{
				onPeriodChanged.accept(selected.key());
			}
		});

		summaryTotal.setFont(FontManager.getRunescapeFont().deriveFont(Font.BOLD, 16f));
		summaryTotal.setForeground(ColorScheme.BRAND_ORANGE);
		stretch(summaryTotal);

		summaryDetail.setFont(FontManager.getRunescapeSmallFont());
		summaryDetail.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stretch(summaryDetail);

		summaryDays.setFont(FontManager.getRunescapeSmallFont());
		summaryDays.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		stretch(summaryDays);

		summaryPanel.setLayout(new BoxLayout(summaryPanel, BoxLayout.Y_AXIS));
		summaryPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		summaryPanel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		summaryPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		summaryPanel.add(periodCombo);
		summaryPanel.add(javax.swing.Box.createVerticalStrut(4));
		summaryPanel.add(summaryTotal);
		summaryPanel.add(summaryDetail);
		summaryPanel.add(summaryDays);
		return summaryPanel;
	}

	private JPanel buildHistoryRow(DayTotal day, TrackingMode mode)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));

		JLabel date = new JLabel(formatDate(day.getDate(), mode));
		date.setFont(FontManager.getRunescapeSmallFont());
		date.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JLabel value = new JLabel(QuantityFormatter.formatNumber(day.getTotal()));
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(day.getTotal() > 0
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.MEDIUM_GRAY_COLOR);

		String breakdown = describe(day);
		if (breakdown != null)
		{
			row.setToolTipText(breakdown);
		}

		// Always present so rows with and without a marker keep the same indent.
		JLabel marker = new JLabel();
		marker.setPreferredSize(new Dimension(14, 0));
		marker.setMinimumSize(new Dimension(14, 0));
		if (day.getOffline() > 0)
		{
			marker.setText("\u25C6");
			marker.setForeground(ColorScheme.BRAND_ORANGE);
			marker.setToolTipText(QuantityFormatter.formatNumber(day.getOffline())
				+ " XP earned while the client was closed");
		}

		row.add(marker, BorderLayout.WEST);
		row.add(date, BorderLayout.CENTER);
		row.add(value, BorderLayout.EAST);
		return row;
	}

	/** Top few skills for that day, shown on hover. */
	private static String describe(DayTotal day)
	{
		if (day.getGains().isEmpty())
		{
			return null;
		}

		StringBuilder sb = new StringBuilder("<html>");
		int shown = 0;
		for (Map.Entry<String, Integer> entry : day.getGains().entrySet())
		{
			if (shown++ == 5)
			{
				sb.append("...");
				break;
			}
			sb.append(Skills.display(entry.getKey()))
				.append(": ")
				.append(QuantityFormatter.formatNumber(entry.getValue()))
				.append("<br>");
		}
		return sb.append("</html>").toString();
	}

	private static String formatDate(String isoDate, TrackingMode mode)
	{
		try
		{
			LocalDate date = LocalDate.parse(isoDate);
			LocalDate today = today(mode);

			if (date.equals(today.minusDays(1)))
			{
				return "Yesterday";
			}
			if (date.isAfter(today.minusDays(7)))
			{
				return WEEKDAY.format(date);
			}
			return DAY.format(date);
		}
		catch (DateTimeParseException ex)
		{
			return isoDate;
		}
	}

	private JButton presetButton(String label, Set<String> selection)
	{
		JButton button = new JButton(label);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.addActionListener(e ->
		{
			syncing = true;
			checkBoxes.forEach((skill, box) -> box.setSelected(selection.contains(skill)));
			syncing = false;
			emitSelection();
		});
		return button;
	}

	private void emitSelection()
	{
		if (syncing)
		{
			return;
		}

		Set<String> selected = new LinkedHashSet<>();
		checkBoxes.forEach((skill, box) ->
		{
			if (box.isSelected())
			{
				selected.add(skill);
			}
		});
		onSelectionChanged.accept(selected);
	}

	/**
	 * Called on the EDT with an immutable snapshot. The checkbox states are synced in place,
	 * but the gain rows are rebuilt: at most 23 rows once a second is cheap enough that
	 * diffing would only add bugs.
	 */
	void update(XpSnapshot snapshot, boolean hideUntrained, boolean showOverall, int goal,
		boolean showChart, boolean showMean, String period, boolean showSummary, long goalProgress,
		boolean countOfflineTowardGoal)
	{
		updateHistory(snapshot, showChart, goal, showMean, period, showSummary, countOfflineTowardGoal);

		goalBar.setVisible(goal > 0);
		if (goal > 0)
		{
			goalBar.setProgress(goalProgress, goal);
			goalBar.setToolTipText(QuantityFormatter.formatNumber(goalProgress)
				+ " of " + QuantityFormatter.formatNumber(goal) + " XP");
		}

		long offline = snapshot.getOfflineTotal();
		offlineLabel.setVisible(offline > 0);
		if (offline > 0)
		{
			offlineLabel.setText(QuantityFormatter.formatNumber(offline) + " earned while client closed");
		}

		int levels = snapshot.getLevelsGained();
		levelsLabel.setVisible(levels > 0);
		levelsLabel.setText(levels == 1 ? "1 level gained" : levels + " levels gained");
		syncSelection(snapshot.getSelection());

		modeLabel.setText(snapshot.getMode().getShortLabel() + selectionSuffix(snapshot));
		totalLabel.setText(QuantityFormatter.formatNumber(snapshot.getTotal()));

		String since = TIME.format(Instant.ofEpochMilli(snapshot.getWindowStartMillis())
			.atZone(ZoneId.systemDefault()));
		String prefix = snapshot.isPartialWindow() ? "tracking since " : "since ";
		windowLabel.setText(prefix + since + formatTimeLeft(snapshot.getWindowEndMillis()));

		boolean showOverallLine = showOverall && snapshot.isFiltered();
		overallLabel.setVisible(showOverallLine);
		if (showOverallLine)
		{
			overallLabel.setText("of " + QuantityFormatter.formatNumber(snapshot.getOverallTotal()) + " overall");
		}

		skillList.removeAll();

		int shown = 0;
		for (Map.Entry<String, Integer> entry : snapshot.getGains().entrySet())
		{
			if (hideUntrained && entry.getValue() <= 0)
			{
				continue;
			}
			skillList.add(buildRow(entry.getKey(), entry.getValue(), snapshot));
			shown++;
		}

		if (!hideUntrained)
		{
			// Selected skills with no gains are still worth a row when the user asked to see them.
			for (String skill : snapshot.getSelection())
			{
				if (!snapshot.getGains().containsKey(skill))
				{
					skillList.add(buildRow(skill, 0, null));
					shown++;
				}
			}
		}

		if (shown == 0)
		{
			emptyLabel.setText(snapshot.getSelection().isEmpty()
				? "No skills selected."
				: "No XP gained yet.");
			skillList.add(emptyLabel);
		}

		skillList.revalidate();
		skillList.repaint();
	}

	private void updateHistory(XpSnapshot snapshot, boolean showChart, int goal, boolean showMean,
		String period, boolean showSummary, boolean countOfflineTowardGoal)
	{
		List<DayTotal> days = snapshot.getHistory();
		historySection.setVisible(!days.isEmpty());
		if (days.isEmpty())
		{
			return;
		}

		chartTitle.setVisible(showChart);
		chart.setVisible(showChart);
		legend.setVisible(showChart && (showMean || goal > 0));
		if (showChart)
		{
			meanKey.setVisible(showMean);
			goalKey.setVisible(goal > 0);
			chart.setShowMean(showMean);
			chart.setCountOfflineTowardGoal(countOfflineTowardGoal);
			chart.setGoal(goal);
			chart.setDays(days, today(snapshot.getMode()));

			int barCount = chart.getBarCount();
			chartTitle.setText(barCount == 1 ? "Past day" : "Past " + barCount + " days");
		}

		updateSummary(days, period, snapshot.getMode(), showSummary);

		historyTitle.setText(days.size() == 1
			? "All recorded days (1)"
			: "All recorded days (" + days.size() + ")");

		historyList.removeAll();
		for (DayTotal day : days)
		{
			historyList.add(buildHistoryRow(day, snapshot.getMode()));
		}
		historyList.revalidate();
		historyList.repaint();
	}

	/**
	 * Totals the archive over the selected period. The archive only holds completed days, so
	 * today is excluded by construction rather than by filtering.
	 */
	private void updateSummary(List<DayTotal> days, String period, TrackingMode mode, boolean showSummary)
	{
		if (!showSummary)
		{
			summaryPanel.setVisible(false);
			return;
		}

		// The UTC archive is keyed by UTC dates, so the period boundary has to be measured in
		// the same zone or it lands a day out for part of every evening.
		LocalDate today = today(mode);
		LocalDate oldest = parseOrNull(days.get(days.size() - 1).getDate());
		int spanDays = oldest == null ? 0 : (int) ChronoUnit.DAYS.between(oldest, today);

		summaryPanel.setVisible(spanDays > 0);
		if (spanDays <= 0)
		{
			return;
		}

		List<PeriodOption> options = buildOptions(spanDays);
		syncOptions(options, period);

		PeriodOption selected = (PeriodOption) periodCombo.getSelectedItem();
		int periodDays = selected == null ? 0 : selected.days;
		int divisor = periodDays > 0 ? periodDays : spanDays;
		LocalDate cutoff = periodDays > 0 ? today.minusDays(periodDays) : oldest;

		long total = 0;
		long best = 0;
		int active = 0;
		for (DayTotal day : days)
		{
			LocalDate date = parseOrNull(day.getDate());
			if (date == null || date.isBefore(cutoff))
			{
				continue;
			}

			total += day.getTotal();
			best = Math.max(best, day.getTotal());
			active++;
		}

		summaryTotal.setText(QuantityFormatter.formatNumber(total) + " XP");
		summaryDetail.setText(QuantityFormatter.formatNumber(total / divisor) + " / day");
		summaryDays.setText("best " + QuantityFormatter.formatNumber(best) + "  \u00b7  "
			+ active + " of " + divisor + (divisor == 1 ? " day played" : " days played"));
	}

	/**
	 * Only offers periods the archive can actually fill, so a selected period is never a
	 * partial one. Months are approximated as 30 days.
	 */
	private static List<PeriodOption> buildOptions(int spanDays)
	{
		List<PeriodOption> options = new ArrayList<>();
		if (spanDays >= 7)
		{
			options.add(new PeriodOption("Last 7 days", 7));
		}
		if (spanDays >= 14)
		{
			options.add(new PeriodOption("Last 14 days", 14));
		}
		for (int month = 1; month <= 12 && month * 30 <= spanDays; month++)
		{
			options.add(new PeriodOption(month == 1 ? "Last month" : "Last " + month + " months", month * 30));
		}

		options.add(new PeriodOption("Whole history", 0));
		return options;
	}

	/**
	 * Rebuilds the dropdown only when the available periods actually changed, so the combo is
	 * not torn down and rebuilt every second while the user is looking at it.
	 */
	private void syncOptions(List<PeriodOption> options, String period)
	{
		boolean same = periodCombo.getItemCount() == options.size();
		for (int i = 0; same && i < options.size(); i++)
		{
			same = periodCombo.getItemAt(i).key().equals(options.get(i).key());
		}

		syncingPeriod = true;
		if (!same)
		{
			periodCombo.removeAllItems();
			for (PeriodOption option : options)
			{
				periodCombo.addItem(option);
			}
		}

		// Falls back to whole history when a stored period is no longer on offer, which happens
		// if retention was lowered or the archive was cleared.
		int index = options.size() - 1;
		for (int i = 0; i < options.size(); i++)
		{
			if (options.get(i).key().equals(period))
			{
				index = i;
				break;
			}
		}
		periodCombo.setSelectedIndex(index);
		syncingPeriod = false;
	}

	private static LocalDate parseOrNull(String isoDate)
	{
		try
		{
			return LocalDate.parse(isoDate);
		}
		catch (DateTimeParseException ex)
		{
			return null;
		}
	}

	/** The current date in whichever zone the active window is keyed by. */
	private static LocalDate today(TrackingMode mode)
	{
		return mode == TrackingMode.UTC_DAY ? LocalDate.now(ZoneOffset.UTC) : LocalDate.now();
	}

	private void syncSelection(Set<String> selection)
	{
		syncing = true;
		checkBoxes.forEach((skill, box) -> box.setSelected(selection.contains(skill)));
		syncing = false;
	}

	private static String selectionSuffix(XpSnapshot snapshot)
	{
		if (snapshot.getSelection().isEmpty())
		{
			return " \u00b7 none selected";
		}
		if (!snapshot.isFiltered())
		{
			return " \u00b7 overall";
		}
		if (snapshot.getSelection().size() == 1)
		{
			return " \u00b7 " + Skills.display(snapshot.getSelection().iterator().next());
		}
		return " \u00b7 " + snapshot.getSelection().size() + " skills";
	}

	private JPanel buildRow(String skillName, int xp, XpSnapshot snapshot)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		JLabel name = new JLabel(Skills.display(skillName) + levelSuffix(skillName, snapshot));
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		BufferedImage icon = skillIcon(skillName);
		if (icon != null)
		{
			JLabel iconLabel = new JLabel(new ImageIcon(icon));
			iconLabel.setPreferredSize(new Dimension(20, 20));
			row.add(iconLabel, BorderLayout.WEST);
		}

		JLabel value = new JLabel(QuantityFormatter.formatNumber(xp));
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(xp > 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.MEDIUM_GRAY_COLOR);

		row.add(name, BorderLayout.CENTER);
		row.add(value, BorderLayout.EAST);
		return row;
	}

	/** "  78→79" when the skill levelled inside the window, blank otherwise. */
	private static String levelSuffix(String skillName, XpSnapshot snapshot)
	{
		if (snapshot == null)
		{
			return "";
		}

		int from = snapshot.startLevel(skillName);
		int to = snapshot.endLevel(skillName);
		return to > from ? "  " + from + "\u2192" + to : "";
	}

	/** " · 4h 12m left" for day windows, blank for the rolling window. */
	private static String formatTimeLeft(long windowEndMillis)
	{
		if (windowEndMillis <= 0)
		{
			return "";
		}

		long remaining = windowEndMillis - System.currentTimeMillis();
		if (remaining <= 0)
		{
			return "";
		}

		Duration duration = Duration.ofMillis(remaining);
		long hours = duration.toHours();
		long minutes = duration.toMinutes() % 60;

		if (hours > 0)
		{
			return " \u00b7 " + hours + "h " + minutes + "m left";
		}
		return minutes > 0 ? " \u00b7 " + minutes + "m left" : " \u00b7 under a minute left";
	}

	private BufferedImage skillIcon(String skillName)
	{
		try
		{
			return skillIconManager.getSkillImage(Skill.valueOf(skillName), true);
		}
		catch (IllegalArgumentException ex)
		{
			// Stored data references a skill this client version does not know about.
			return null;
		}
	}

	/** Left-aligns a child of a vertical BoxLayout. Width is handled by WideLabel/WidePanel. */
	private static void stretch(JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
	}

	/** One entry in the period dropdown. days of 0 means the whole archive. */
	private static final class PeriodOption
	{
		private final String label;
		private final int days;

		PeriodOption(String label, int days)
		{
			this.label = label;
			this.days = days;
		}

		String key()
		{
			return days <= 0 ? "ALL" : Integer.toString(days);
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/**
	 * Fills the width of a vertical BoxLayout instead of shrinking to its text, while keeping
	 * its natural height. Recomputed on every layout pass rather than captured once, so it
	 * stays correct when text, font, or border are set later.
	 */
	private static class WideLabel extends JLabel
	{
		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	/** Same, for a container that should fill the width but not absorb vertical slack. */
	private static class WidePanel extends JPanel
	{
		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}
}

package com.dailyxptracker;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.Notifier;
import net.runelite.client.util.QuantityFormatter;

@PluginDescriptor(
	name = "Daily XP Tracker",
	description = "Tracks the XP you have gained today, since midnight or over a rolling 24 hours",
	tags = {"xp", "experience", "daily", "today", "tracker", "skilling"}
)
public class DailyXpPlugin extends Plugin
{
	/** How often the stored state is written to disk while logged in. */
	private static final long FLUSH_INTERVAL_MILLIS = 15_000L;
	private static final long UI_INTERVAL_MILLIS = 1_000L;

	/**
	 * Measured from the last game tick the plugin saw to the moment it next loads. Under this,
	 * the gap is a disconnect, a world hop, or a client restart, and any XP found in it was
	 * earned at this client. Tagging it offline would wrongly exclude it from the goal. Over
	 * it, the whole gap counts as time away. XP is counted toward the day either way.
	 */
	private static final long AWAY_THRESHOLD_MILLIS = 3 * 60 * 1000L; // 3 minutes

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private DailyXpConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private XpTracker tracker;

	@Inject
	private DailyXpOverlay overlay;

	@Inject
	private Notifier notifier;

	private DailyXpPanel panel;
	private NavigationButton navButton;

	/**
	 * Last XP value seen per skill this session. A skill missing from this map has not been
	 * observed yet, so its next StatChanged is a seeding value and not a gain — this is what
	 * stops the login flood of StatChanged events being counted as XP earned.
	 */
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);

	private boolean profileLoadPending;
	private long lastFlush;
	private long lastUiUpdate;

	@Provides
	DailyXpConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DailyXpConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new DailyXpPanel(skillIconManager, this::applySelection, this::applyPeriod, this::requestReset);

		BufferedImage icon = ImageUtil.loadImageResource(DailyXpPlugin.class, "/panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Daily XP Tracker")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		lastXp.clear();

		// Enabling the plugin mid-session: no StatChanged events are coming until the player
		// next gains XP, so seed and load straight away.
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			profileLoadPending = true;
		}
	}

	@Override
	protected void shutDown()
	{
		tracker.save();
		tracker.unload();

		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);

		lastXp.clear();
		profileLoadPending = false;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGING_IN:
				// A different account may be logging in, so drop the seed values. World hopping
				// is deliberately not handled here: XP does not reset on a hop, and the repeat
				// StatChanged events it produces resolve to a delta of zero.
				lastXp.clear();
				break;

			case LOGGED_IN:
				profileLoadPending = true;
				break;

			case LOGIN_SCREEN:
			case CONNECTION_LOST:
			case HOPPING:
				// Best effort — the RS profile is usually still active at this point. The periodic
				// flush is what actually guarantees durability.
				tracker.save();
				break;

			default:
				break;
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		if (isOverall(skill))
		{
			return;
		}

		Integer previous = lastXp.put(skill, event.getXp());
		if (previous == null)
		{
			// First sighting this session. Seed only.
			return;
		}

		int delta = event.getXp() - previous;
		if (delta <= 0)
		{
			return;
		}

		if (tracker.isLoaded())
		{
			tracker.record(skill.name(), delta, System.currentTimeMillis());
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		long now = System.currentTimeMillis();

		if (profileLoadPending)
		{
			loadProfile(now);
			profileLoadPending = false;
		}

		if (!tracker.isLoaded())
		{
			return;
		}

		Map<String, Integer> currentXp = readCurrentXp();

		// Keep the last-observed XP level with live XP before testing for rollover, so a day
		// closed out at midnight includes everything up to the boundary.
		tracker.observe(currentXp, now);

		// Handles midnight passing while logged in: the date string changes, the finished day
		// is archived, and the baseline is re-snapshotted, all within one tick of 00:00.
		tracker.checkDayRollover(currentXp, zone(), now, config.historyDays());
		tracker.prune(now);

		if (tracker.isDirty() && now - lastFlush >= FLUSH_INTERVAL_MILLIS)
		{
			tracker.updateLastKnown(currentXp, now);
			tracker.save();
			lastFlush = now;
		}

		if (now - lastUiUpdate >= UI_INTERVAL_MILLIS)
		{
			publish(currentXp, now);
			lastUiUpdate = now;
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		tracker.save();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DailyXpConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Republish immediately so mode and selection changes are reflected without waiting
		// for the next UI tick.
		clientThread.invoke(() ->
		{
			if (!tracker.isLoaded() || client.getLocalPlayer() == null)
			{
				return;
			}
			tracker.enforceRetention(config.historyDays());
			publish(readCurrentXp(), System.currentTimeMillis());
		});
	}

	/** Persists a period chosen from the panel dropdown. */
	private void applyPeriod(String period)
	{
		configManager.setConfiguration(DailyXpConfig.GROUP, DailyXpConfig.KEY_SUMMARY_PERIOD, period);
	}

	/**
	 * Persists a selection made in the side panel. Recording is never filtered, so changing
	 * the selection re-totals existing history rather than discarding it.
	 */
	private void applySelection(Set<String> skills)
	{
		if (skills.size() == Skills.all().size())
		{
			configManager.setConfiguration(DailyXpConfig.GROUP, DailyXpConfig.KEY_SKILL_FILTER, SkillFilter.ALL);
			return;
		}

		configManager.setConfiguration(DailyXpConfig.GROUP, DailyXpConfig.KEY_CUSTOM_SKILLS,
			Skills.join(new LinkedHashSet<>(skills)));
		configManager.setConfiguration(DailyXpConfig.GROUP, DailyXpConfig.KEY_SKILL_FILTER, SkillFilter.CUSTOM);
	}

	private Set<String> selection()
	{
		return Skills.resolve(config.skillFilter(), config.customSkills());
	}

	/**
	 * Loads the stored state for the account that just logged in, reconciles anything that
	 * happened while we were not running, and seeds the per-skill XP map.
	 */
	private void loadProfile(long now)
	{
		tracker.load(now);
		tracker.enforceRetention(config.historyDays());

		Map<String, Integer> currentXp = readCurrentXp();

		// Roll over first: the new day's baseline is derived from lastKnownXp, so XP earned
		// while away lands on the day being entered. Recording the offline tally afterwards
		// files it against that same day rather than the one just closed.
		tracker.checkDayRollover(currentXp, zone(), now, config.historyDays());

		Map<String, Integer> offline = tracker.detectOfflineGains(currentXp);
		if (!offline.isEmpty())
		{
			// A short gap means the XP was earned at this client and only missed because we
			// were not watching such as a dropped connection mid-kill. Tagging that as offline
			// would wrongly exclude it from the goal, so only a long gap counts.
			if (tracker.millisSinceLastSeen(now) >= AWAY_THRESHOLD_MILLIS)
			{
				tracker.recordOffline(offline);
			}

			if (config.countOfflineGains())
			{
				offline.forEach((skill, delta) -> tracker.record(skill, delta, now));
			}
		}

		tracker.updateLastKnown(currentXp, now);

		lastXp.clear();
		for (Skill skill : Skill.values())
		{
			if (isOverall(skill))
			{
				continue;
			}
			lastXp.put(skill, client.getSkillExperience(skill));
		}

		tracker.save();
		lastFlush = now;
		publish(currentXp, now);
	}

	private void requestReset()
	{
		clientThread.invoke(() ->
		{
			if (!tracker.isLoaded() || client.getLocalPlayer() == null)
			{
				return;
			}

			long now = System.currentTimeMillis();
			Map<String, Integer> currentXp = readCurrentXp();
			tracker.reset(currentXp, zone(), now, config.historyDays());
			publish(currentXp, now);
		});
	}

	private void publish(Map<String, Integer> currentXp, long now)
	{
		// Retention already bounds what is stored, so display shows everything that survived.
		int historyLimit = config.showHistory() ? Integer.MAX_VALUE : 0;
		XpSnapshot snapshot = tracker.snapshot(config.trackingMode(), selection(), currentXp, zone(), now, historyLimit);
		overlay.setSnapshot(snapshot);

		checkGoal(snapshot);

		boolean hideUntrained = config.hideUntrained();
		boolean showOverall = config.showOverallWhenFiltered();
		int goal = Math.max(0, config.xpGoal());
		boolean showChart = config.showChart();
		boolean showMean = config.showMeanLine();
		String period = config.summaryPeriod();
		boolean showSummary = config.showPeriodSummary();
		long goalProgress = goalProgress(snapshot);
		boolean countOfflineTowardGoal = config.countOfflineTowardGoal();

		DailyXpPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (target.isShowing())
				{
					target.update(snapshot, hideUntrained, showOverall, goal, showChart, showMean,
						period, showSummary, goalProgress, countOfflineTowardGoal);
				}
			});
		}
	}

	/** Goal progress, with offline XP excluded unless the player opted in. */
	private long goalProgress(XpSnapshot snapshot)
	{
		return config.countOfflineTowardGoal()
			? snapshot.getTotal()
			: Math.max(0, snapshot.getTotal() - snapshot.getOfflineTotal());
	}

	/**
	 * Fires once per day when the goal is first met. Keyed on the day so it survives a relog,
	 * and skipped for the rolling window, which never resets and so would fire forever.
	 */
	private void checkGoal(XpSnapshot snapshot)
	{
		int goal = config.xpGoal();
		if (goal <= 0 || !config.notifyOnGoal() || snapshot.getMode() == TrackingMode.ROLLING_24H)
		{
			return;
		}

		long progress = goalProgress(snapshot);
		if (progress < goal)
		{
			return;
		}

		String dayKey = tracker.currentDayKey(snapshot.getMode());
		if (!tracker.goalPending(dayKey))
		{
			return;
		}

		tracker.markGoalNotified(dayKey);
		notifier.notify("Daily XP goal reached: "
			+ QuantityFormatter.formatNumber(progress) + " XP");
	}

	private Map<String, Integer> readCurrentXp()
	{
		Map<String, Integer> current = new HashMap<>();
		for (Skill skill : Skill.values())
		{
			if (isOverall(skill))
			{
				continue;
			}
			current.put(skill.name(), client.getSkillExperience(skill));
		}
		return current;
	}

	private ZoneId zone()
	{
		return ZoneId.systemDefault();
	}

	/**
	 * Older API versions include an OVERALL constant in the Skill enum which would double count
	 * every gain. Compared by name so this compiles against versions where it has been removed.
	 */
	private static boolean isOverall(Skill skill)
	{
		return "OVERALL".equals(skill.name());
	}
}

