package com.dailyxptracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

class GoalBar extends JComponent
{
	private static final int HEIGHT = 16;

	private long value;
	private long goal;

	GoalBar()
	{
		setToolTipText("Progress toward your daily XP goal");
	}

	void setProgress(long value, long goal)
	{
		this.value = value;
		this.goal = goal;
		repaint();
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(0, HEIGHT);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, HEIGHT);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(0, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int w = getWidth();
		int h = getHeight();

		g2.setColor(ColorScheme.DARK_GRAY_COLOR);
		g2.fillRect(0, 0, w, h);

		double fraction = goal <= 0 ? 0 : Math.min(1.0, (double) value / (double) goal);
		g2.setColor(fraction >= 1.0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE);
		g2.fillRect(0, 0, (int) Math.round(w * fraction), h);

		String text = Math.round(fraction * 100) + "%";
		g2.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g2.getFontMetrics();
		g2.setColor(Color.WHITE);
		g2.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent()) / 2 - 1);

		g2.dispose();
	}
}

package com.dailyxptracker;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import java.awt.Color;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.QuantityFormatter;
import java.util.HashMap;
import java.util.Map;

class HistoryChart extends JComponent
{
	private static final int HEIGHT = 56;
	/** More than this and the bars get too narrow to read in a sidebar. */
	static final int MAX_BARS = 14;
	private static final DateTimeFormatter TOOLTIP_DAY = DateTimeFormatter.ofPattern("EEE d MMM");

	private long goal;
	private boolean countOfflineTowardGoal;
	private boolean showMean = true;
	private List<DayTotal> days = Collections.emptyList();

	HistoryChart()
	{
		// Registers with ToolTipManager; the real text comes from getToolTipText(MouseEvent).
		setToolTipText("");
	}

	void setGoal(long goal)
	{
		this.goal = Math.max(0, goal);
		repaint();
	}

	void setCountOfflineTowardGoal(boolean countOfflineTowardGoal)
	{
		this.countOfflineTowardGoal = countOfflineTowardGoal;
		repaint();
	}

	void setShowMean(boolean showMean)
	{
		this.showMean = showMean;
		repaint();
	}

	/**
	 * Builds the window the chart draws: one entry per calendar day, with missing days filled
	 * in as zero. The window ends yesterday (the archive never holds today) and starts either
	 * MAX_BARS days back or when tracking began, whichever is later — clamping to the oldest
	 * entry stops a fresh install showing empty bars for days it was never running.
	 */
	void setDays(List<DayTotal> newestFirst, LocalDate today)
	{
		List<DayTotal> window = new ArrayList<>();
		this.days = window;

		if (newestFirst.isEmpty() || today == null)
		{
			repaint();
			return;
		}

		LocalDate oldest = parseOrNull(newestFirst.get(newestFirst.size() - 1).getDate());
		if (oldest == null)
		{
			repaint();
			return;
		}

		Map<String, DayTotal> byDate = new HashMap<>();
		for (DayTotal day : newestFirst)
		{
			byDate.put(day.getDate(), day);
		}

		LocalDate end = today.minusDays(1);
		LocalDate start = today.minusDays(MAX_BARS);
		if (start.isBefore(oldest))
		{
			start = oldest;
		}

		for (LocalDate date = start; !date.isAfter(end); date = date.plusDays(1))
		{
			String key = date.toString();
			DayTotal existing = byDate.get(key);
			window.add(existing != null ? existing : new DayTotal(key, 0, 0, Collections.emptyMap()));
		}

		repaint();
	}

	/** The part of a day's total that counts toward the goal. */
	private long countedTotal(DayTotal day)
	{
		return countOfflineTowardGoal
			? day.getTotal()
			: Math.max(0, day.getTotal() - day.getOffline());
	}

	/** How many bars are actually drawn, so the panel can label the chart accurately. */
	int getBarCount()
	{
		return days.size();
	}

	private static LocalDate parseOrNull(String isoDate)
	{
		try
		{
			return LocalDate.parse(isoDate);
		}
		catch (DateTimeParseException ex)
		{
			return null;
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(0, HEIGHT);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, HEIGHT);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(0, HEIGHT);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		if (days.isEmpty())
		{
			return;
		}

		Graphics2D g2 = (Graphics2D) g.create();
		int w = getWidth();
		int h = getHeight();

		long max = 0;
		long sum = 0;
		for (DayTotal day : days)
		{
			max = Math.max(max, day.getTotal());
			sum += day.getTotal();
		}

		// The goal shares the vertical scale, so its line is always on screen even in a week
		// where nothing came close to it.
		long scale = Math.max(max, goal);
		if (scale <= 0)
		{
			g2.dispose();
			return;
		}


		int gap = days.size() > 1 ? 2 : 0;
		for (int i = 0; i < days.size(); i++)
		{
			DayTotal day = days.get(i);
			long total = day.getTotal();
			long counted = countedTotal(day);

			int x = (int) ((long) w * i / days.size());
			int next = (int) ((long) w * (i + 1) / days.size());
			int barWidth = Math.max(1, next - x - gap);

			int barHeight = Math.max(2, (int) Math.round((double) total / scale * (h - 2)));
			int y = h - barHeight;

			Color color = barColor(total, counted, max);
			g2.setColor(color);
			g2.fillRect(x, y, barWidth, barHeight);

			if (counted < total)
			{
				int countedHeight = (int) Math.round((double) counted / scale * (h - 2));
				int offlineHeight = barHeight - countedHeight;
				if (offlineHeight > 0)
				{
					g2.setColor(dim(color));
					g2.fillRect(x, y, barWidth, offlineHeight);
				}
			}
		}

		if (showMean)
		{
			long mean = sum / days.size();
			int meanY = h - (int) Math.round((double) mean / scale * (h - 2));
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g2.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f,
				new float[]{2f, 3f}, 0f));
			g2.drawLine(0, meanY, w, meanY);
		}
		// Drawn last so it sits above the bars and the mean. Solid and white to separate it
		// from the dashed grey mean line.
		if (goal > 0)
		{
			int goalY = h - (int) Math.round((double) goal / scale * (h - 2));
			g2.setColor(Color.WHITE);
			g2.setStroke(new BasicStroke(1f));
			g2.drawLine(0, goalY, w, goalY);
		}

		g2.dispose();
	}

	/**
	 * Green once a day met the goal, orange otherwise. With no goal set there is nothing to
	 * pass or fail, so it falls back to highlighting the best day in view.
	 */
	private Color barColor(long total, long counted, long max)
	{
		if (total <= 0)
		{
			// A day with nothing recorded is neither a pass nor a fail — grey it out so it
			// reads as "did not play" rather than "played badly".
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		if (goal > 0)
		{
			return counted >= goal ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.BRAND_ORANGE;
		}
		return total >= max ? ColorScheme.BRAND_ORANGE : ColorScheme.PROGRESS_COMPLETE_COLOR;
	}

	/** Halved brightness, so an excluded segment reads as the same bar rather than a new color. */
	private static Color dim(Color color)
	{
		return new Color(color.getRed() / 2, color.getGreen() / 2, color.getBlue() / 2);
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		if (days.isEmpty())
		{
			return null;
		}

		int index = (int) ((long) event.getX() * days.size() / getWidth());
		if (index < 0 || index >= days.size())
		{
			return null;
		}

		DayTotal day = days.get(index);
		if (day.getTotal() <= 0)
		{
			return formatDay(day.getDate()) + ": no XP recorded";
		}
		String text = formatDay(day.getDate()) + ": " + QuantityFormatter.formatNumber(day.getTotal()) + " XP";
		long counted = countedTotal(day);
		if (counted < day.getTotal())
		{
			text += " (" + QuantityFormatter.formatNumber(day.getTotal() - counted) + " while client closed)";
		}

		if (goal <= 0)
		{
			return text;
		}

		long difference = counted - goal;
		return difference >= 0
			? text + ", " + QuantityFormatter.formatNumber(difference) + " over goal"
			: text + ", " + QuantityFormatter.formatNumber(-difference) + " short";
	}

	private static String formatDay(String isoDate)
	{
		try
		{
			return TOOLTIP_DAY.format(LocalDate.parse(isoDate));
		}
		catch (DateTimeParseException ex)
		{
			return isoDate;
		}
	}
}

