package com.dailyxptracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Skill;

/**
 * Skill naming and selection helpers. Skills are identified everywhere by their enum
 * constant name ("SLAYER") so that stored data and config strings stay valid across API
 * changes.
 */
final class Skills
{
	/** The seven skills that determine combat level. */
	private static final Set<String> COMBAT = Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(
		"ATTACK", "STRENGTH", "DEFENCE", "HITPOINTS", "RANGED", "MAGIC", "PRAYER"
	)));

	private Skills()
	{
	}

	/**
	 * Every real skill, in API order. OVERALL is excluded by name rather than by referencing
	 * the constant, because it has been removed from the enum in newer API versions.
	 */
	static List<String> all()
	{
		List<String> names = new ArrayList<>();
		for (Skill skill : Skill.values())
		{
			if (!"OVERALL".equals(skill.name()))
			{
				names.add(skill.name());
			}
		}
		return names;
	}

	static boolean isCombat(String skill)
	{
		return COMBAT.contains(skill);
	}

	/** Turns a filter plus the stored custom list into the concrete set of skills to display. */
	static Set<String> resolve(SkillFilter filter, String customList)
	{
		switch (filter)
		{
			case COMBAT:
				return retainKnown(COMBAT);

			case NON_COMBAT:
			{
				Set<String> result = new LinkedHashSet<>(all());
				result.removeAll(COMBAT);
				return result;
			}

			case CUSTOM:
				// An empty selection is allowed: "None" is how you clear the board before
				// ticking the two skills you actually care about.
				return parse(customList);

			case ALL:
			default:
				return new LinkedHashSet<>(all());
		}
	}

	/**
	 * Parses a comma separated list, tolerating case, whitespace and unknown entries so that
	 * hand-edited config values do not break the plugin.
	 */
	static Set<String> parse(String csv)
	{
		Set<String> result = new LinkedHashSet<>();
		if (csv == null || csv.trim().isEmpty())
		{
			return result;
		}

		Set<String> known = new HashSet<>(all());
		for (String token : csv.split(","))
		{
			String normalised = token.trim().toUpperCase().replace(' ', '_');
			if (known.contains(normalised))
			{
				result.add(normalised);
			}
		}
		return result;
	}

	static String join(Collection<String> skills)
	{
		return String.join(",", skills);
	}

	/** ATTACK -> Attack. Avoids depending on Skill#getName, which has moved between versions. */
	static String display(String enumName)
	{
		String lower = enumName.toLowerCase();
		return Character.toUpperCase(lower.charAt(0)) + lower.substring(1);
	}

	/** Drops any skill the running client does not know about. */
	private static Set<String> retainKnown(Set<String> skills)
	{
		Set<String> known = new HashSet<>(all());
		Set<String> result = new LinkedHashSet<>();
		for (String skill : skills)
		{
			if (known.contains(skill))
			{
				result.add(skill);
			}
		}
		return result;
	}
}

