package com.dailyxptracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Experience;

/**
 * An immutable view of the current totals, handed from the client thread to the UI.
 * Nothing here reads from the client, so Swing and the overlay can use it freely.
 */
class XpSnapshot
{
	private final TrackingMode mode;
	private final Set<String> selection;
	private final Map<String, Integer> gains;
	private final long total;
	private final long overallTotal;
	private final long offlineTotal;
	private final long windowStartMillis;
	private final boolean partialWindow;
	private final List<DayTotal> history;
	private final long windowEndMillis;
	private final Map<String, Integer> startXp;
	private final int levelsGained;

	XpSnapshot(
		TrackingMode mode,
		Set<String> selection,
		Map<String, Integer> selectedGains,
		long overallTotal,
		long offlineTotal,
		long windowStartMillis,
		long windowEndMillis,
		boolean partialWindow,
		List<DayTotal> history,
		Map<String, Integer> startXp)
	{
		this.history = Collections.unmodifiableList(new ArrayList<>(history));
		this.mode = mode;
		this.selection = Collections.unmodifiableSet(new LinkedHashSet<>(selection));
		this.gains = Collections.unmodifiableMap(new LinkedHashMap<>(selectedGains));
		this.overallTotal = overallTotal;
		this.offlineTotal = offlineTotal;
		this.windowStartMillis = windowStartMillis;
		this.partialWindow = partialWindow;
		this.windowEndMillis = windowEndMillis;
		this.startXp = Collections.unmodifiableMap(new LinkedHashMap<>(startXp));

		long sum = 0;
		for (int v : selectedGains.values())
		{
			sum += v;
		}
		this.total = sum;
		int levels = 0;
		for (Map.Entry<String, Integer> entry : selectedGains.entrySet())
		{
			int from = startXp.getOrDefault(entry.getKey(), 0);
			levels += levelOf(from + entry.getValue()) - levelOf(from);
		}
		this.levelsGained = levels;
	}

	/** Level at the start of the window for a skill present in getGains(). */
	int startLevel(String skill)
	{
		return levelOf(startXp.getOrDefault(skill, 0));
	}

	/** Level right now for a skill present in getGains(). */
	int endLevel(String skill)
	{
		return levelOf(startXp.getOrDefault(skill, 0) + gains.getOrDefault(skill, 0));
	}

	/** Total levels gained across the selection. Virtual levels are not counted. */
	int getLevelsGained()
	{
		return levelsGained;
	}

	/** When the window closes, or 0 for the rolling window, which has no end. */
	long getWindowEndMillis()
	{
		return windowEndMillis;
	}

	private static int levelOf(int xp)
	{
		return xp <= 0 ? 1 : Math.min(99, Experience.getLevelForXp(xp));
	}

	TrackingMode getMode()
	{
		return mode;
	}

	/** The skills currently included in the total, whether or not they gained any XP. */
	Set<String> getSelection()
	{
		return selection;
	}

	/** Selected skills that gained XP, ordered highest first. */
	Map<String, Integer> getGains()
	{
		return gains;
	}

	/** Sum across the selected skills. */
	long getTotal()
	{
		return total;
	}

	/** Sum across every skill, regardless of selection. */
	long getOverallTotal()
	{
		return overallTotal;
	}

	/** How much of the total was earned while the client was closed. */
	long getOfflineTotal()
	{
		return offlineTotal;
	}

	/** True when the selection is a strict subset, so the headline is not overall XP. */
	boolean isFiltered()
	{
		return selection.size() < Skills.all().size();
	}

	long getWindowStartMillis()
	{
		return windowStartMillis;
	}

	/** Completed days, newest first, already totalled over the current selection. */
	List<DayTotal> getHistory()
	{
		return history;
	}

	/**
	 * True when the plugin has not been installed long enough to cover the whole window,
	 * so the number shown is smaller than the window implies.
	 */
	boolean isPartialWindow()
	{
		return partialWindow;
	}
}

package com.dailyxptracker;

import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Everything persisted for a single RuneScape account, stored as one JSON blob in the
 * RS profile config. Skills are keyed by their enum constant name ("ATTACK") rather than
 * ordinal so that the stored data survives skills being added to or removed from the API.
 */
class XpState
{
	static final int CURRENT_VERSION = 1;

	int version = CURRENT_VERSION;

	/** ISO date the localBaseline snapshot was taken on, in the user's zone. */
	String localDayKey;

	/** ISO date the utcBaseline snapshot was taken on, in UTC. */
	String utcDayKey;

	/** skill -> total XP at the start of the current local day */
	Map<String, Integer> localBaseline = new HashMap<>();

	/** skill -> total XP at the start of the current UTC day */
	Map<String, Integer> utcBaseline = new HashMap<>();

	/** bucket index (epoch millis / BUCKET_MILLIS) -> skill -> XP gained inside that bucket */
	TreeMap<Long, Map<String, Integer>> buckets = new TreeMap<>();

	/** skill -> the last XP value we observed, used to detect gains made while we were not running */
	Map<String, Integer> lastKnownXp = new HashMap<>();

	/** Offline XP attributed to the day currently in progress, per window. */
	Map<String, Integer> offlineLocal = new HashMap<>();
	Map<String, Integer> offlineUtc = new HashMap<>();

	/** Offline XP for completed days, ISO date -> skill -> XP. */
	TreeMap<String, Map<String, Integer>> offlineHistoryLocal = new TreeMap<>();
	TreeMap<String, Map<String, Integer>> offlineHistoryUtc = new TreeMap<>();

	/**
	 * Completed days, ISO date -> skill -> XP gained that day. Written when a baseline is
	 * about to be overwritten at rollover. Always covers every skill, never just the
	 * selected ones, so that changing the selection re-totals history rather than losing it.
	 */
	TreeMap<String, Map<String, Integer>> historyLocal = new TreeMap<>();
	TreeMap<String, Map<String, Integer>> historyUtc = new TreeMap<>();

	/** the day key the goal notification last fired for, so it fires once per day */
	String goalNotifiedDayKey;

	/** when we last observed this account */
	long lastSeenMillis;

	/** when this account was first seen by the plugin, so the UI can say "tracking since ..." */
	long trackingStartedMillis;

	/**
	 * Gson leaves fields absent from the JSON as null, so anything read off disk gets repaired here.
	 */
	void repair()
	{
		if (localBaseline == null)
		{
			localBaseline = new HashMap<>();
		}
		if (utcBaseline == null)
		{
			utcBaseline = new HashMap<>();
		}
		if (buckets == null)
		{
			buckets = new TreeMap<>();
		}
		if (lastKnownXp == null)
		{
			lastKnownXp = new HashMap<>();
		}
		if (historyLocal == null)
		{
			historyLocal = new TreeMap<>();
		}
		if (historyUtc == null)
		{
			historyUtc = new TreeMap<>();
		}
		if (offlineLocal == null)
		{
			offlineLocal = new HashMap<>();
		}
		if (offlineUtc == null)
		{
			offlineUtc = new HashMap<>();
		}
		if (offlineHistoryLocal == null)
		{
			offlineHistoryLocal = new TreeMap<>();
		}
		if (offlineHistoryUtc == null)
		{
			offlineHistoryUtc = new TreeMap<>();
		}
	}
}

package com.dailyxptracker;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Owns the stored state and all of the windowing maths. Everything in here is called from
 * the client thread only.
 */
@Singleton
class XpTracker
{
	private static final Logger log = LoggerFactory.getLogger(XpTracker.class);

	/** Rolling-window resolution. 5 minutes gives at most 288 buckets in a 24h window. */
	static final long BUCKET_MILLIS = 5 * 60 * 1000L;
	static final long WINDOW_MILLIS = 24 * 60 * 60 * 1000L;

	private static final String STATE_KEY = "state";

	private final ConfigManager configManager;
	private final Gson gson;

	private XpState state = new XpState();
	private boolean loaded;
	private boolean dirty;

	@Inject
	XpTracker(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	boolean isLoaded()
	{
		return loaded;
	}

	boolean isDirty()
	{
		return dirty;
	}

	/** How long since the plugin last observed this account, or forever if it never has. */
	long millisSinceLastSeen(long now)
	{
		return state.lastSeenMillis == 0 ? Long.MAX_VALUE : Math.max(0, now - state.lastSeenMillis);
	}

	/**
	 * Reads the state for whichever RS profile is currently active. Must only be called once
	 * the player is logged in, otherwise there is no profile to read from.
	 */
	void load(long now)
	{
		XpState read = null;
		try
		{
			String json = configManager.getRSProfileConfiguration(DailyXpConfig.GROUP, STATE_KEY);
			if (json != null && !json.isEmpty())
			{
				read = gson.fromJson(json, XpState.class);
			}
		}
		catch (JsonSyntaxException ex)
		{
			log.warn("stored daily xp state was unreadable, starting fresh", ex);
		}

		state = read != null ? read : new XpState();
		state.repair();

		if (state.trackingStartedMillis == 0)
		{
			state.trackingStartedMillis = now;
		}

		loaded = true;
		dirty = false;
	}

	void unload()
	{
		loaded = false;
		state = new XpState();
	}

	void save()
	{
		if (!loaded)
		{
			return;
		}

		try
		{
			configManager.setRSProfileConfiguration(DailyXpConfig.GROUP, STATE_KEY, gson.toJson(state));
			dirty = false;
		}
		catch (Exception ex)
		{
			// Most likely there is no active profile any more, e.g. we raced a logout. Keep the
			// in-memory state dirty so the next successful save picks it up.
			log.warn("could not persist daily xp state", ex);
		}
	}

	/**
	 * Records XP into the rolling window. Day-based windows need no bookkeeping here because
	 * they are derived from a baseline against live XP.
	 */
	void record(String skill, int delta, long now)
	{
		if (delta <= 0)
		{
			return;
		}

		long bucket = now / BUCKET_MILLIS;
		state.buckets.computeIfAbsent(bucket, k -> new HashMap<>()).merge(skill, delta, Integer::sum);
		dirty = true;
		prune(now);
	}

	/**
	 * Notes XP that was earned while the plugin was not watching. Tracked separately from the
	 * day total so the goal can exclude it and the panel can show where it came from.
	 */
	void recordOffline(Map<String, Integer> gains)
	{
		if (gains.isEmpty())
		{
			return;
		}

		gains.forEach((skill, xp) ->
		{
			state.offlineLocal.merge(skill, xp, Integer::sum);
			state.offlineUtc.merge(skill, xp, Integer::sum);
		});
		dirty = true;
	}

	/**
	 * Moves the offline tally onto a new day alongside the baseline. Kept out of rollTo so the
	 * archive and the offline log stay independently readable.
	 */
	private void rollOffline(
		TreeMap<String, Map<String, Integer>> offlineHistory,
		Map<String, Integer> offlineCurrent,
		String previousKey,
		String newKey,
		int historyDays)
	{
		boolean movedForward = previousKey == null || newKey.compareTo(previousKey) > 0;
		if (movedForward && previousKey != null && historyDays > 0 && !offlineCurrent.isEmpty())
		{
			offlineHistory.put(previousKey, new HashMap<>(offlineCurrent));
		}

		offlineCurrent.clear();

		// Re-entering an archived day (the clock moved back) resumes its offline tally too.
		Map<String, Integer> resumed = offlineHistory.remove(newKey);
		if (resumed != null)
		{
			offlineCurrent.putAll(resumed);
		}
	}

	/** Drops buckets that have fallen out of the rolling window. */
	void prune(long now)
	{
		long cutoff = (now - WINDOW_MILLIS) / BUCKET_MILLIS;
		if (!state.buckets.isEmpty() && state.buckets.firstKey() < cutoff)
		{
			state.buckets.headMap(cutoff, false).clear();
			dirty = true;
		}
	}

	/**
	 * Re-snapshots the midnight baselines if a day boundary has passed since they were taken.
	 * Called on login and on every tick, so it covers both "the client was closed overnight" and
	 * "midnight passed while I was logged in".
	 *
	 * @return true if either baseline was reset
	 */
	boolean checkDayRollover(Map<String, Integer> currentXp, ZoneId localZone, long now, int historyDays)
	{
		boolean reset = false;
		Instant instant = Instant.ofEpochMilli(now);

		String localKey = LocalDate.ofInstant(instant, localZone).toString();
		if (!localKey.equals(state.localDayKey))
		{
			rollOffline(state.offlineHistoryLocal, state.offlineLocal, state.localDayKey, localKey, historyDays);
			state.localBaseline = rollTo(state.historyLocal, state.localDayKey, localKey,
				state.localBaseline, currentXp, historyDays);
			state.localDayKey = localKey;
			reset = true;
		}

		String utcKey = LocalDate.ofInstant(instant, ZoneOffset.UTC).toString();
		if (!utcKey.equals(state.utcDayKey))
		{
			rollOffline(state.offlineHistoryUtc, state.offlineUtc, state.utcDayKey, utcKey, historyDays);
			state.utcBaseline = rollTo(state.historyUtc, state.utcDayKey, utcKey,
				state.utcBaseline, currentXp, historyDays);
			state.utcDayKey = utcKey;
			reset = true;
		}

		// Self-heal: the day in progress must never also sit in the archive as a completed day.
		// A clock or timezone change can leave it in both, so fold the archived total back into
		// the live baseline instead of leaving it stranded. Runs every call, not just on
		// rollover, so an already-inconsistent state repairs itself on the next tick.
		Map<String, Integer> staleLocal = state.historyLocal.remove(state.localDayKey);
		if (staleLocal != null)
		{
			state.localBaseline = foldArchivedIntoBaseline(state.localBaseline, staleLocal);
			dirty = true;
		}

		Map<String, Integer> staleUtc = state.historyUtc.remove(state.utcDayKey);
		if (staleUtc != null)
		{
			state.utcBaseline = foldArchivedIntoBaseline(state.utcBaseline, staleUtc);
			dirty = true;
		}

		if (reset)
		{
			dirty = true;
		}
		return reset;
	}

	/**
	 * Moves a day window onto a new date, archiving the old one where that makes sense.
	 *
	 * @return the baseline for the day being entered
	 */
	private Map<String, Integer> rollTo(
		TreeMap<String, Map<String, Integer>> history,
		String previousKey,
		String newKey,
		Map<String, Integer> previousBaseline,
		Map<String, Integer> currentXp,
		int historyDays)
	{
		// Moving backwards means the clock or the timezone shifted back, not that a day
		// finished. Whatever accumulated under the later date is discarded rather than filed,
		// since it never really happened.
		boolean movedForward = previousKey == null || newKey.compareTo(previousKey) > 0;
		if (movedForward)
		{
			archiveDay(history, previousKey, previousBaseline, historyDays);
		}

		// If the day being entered is already archived, resume it rather than restarting from
		// zero: choose a baseline that reproduces the stored total against live XP.
		Map<String, Integer> archived = history.remove(newKey);
		if (archived == null)
		{
			return carriedBaseline(currentXp);
		}

		return foldArchivedIntoBaseline(currentXp, archived);
	}

	/**
	 * Lowers a baseline by an already-recorded total, so that XP counts on top of it instead of
	 * replacing it. Used both when re-entering an archived day and when repairing a state where
	 * the current day was left sitting in the archive.
	 */
	private static Map<String, Integer> foldArchivedIntoBaseline(
		Map<String, Integer> baseline,
		Map<String, Integer> archived)
	{
		Map<String, Integer> adjusted = new HashMap<>();
		for (Map.Entry<String, Integer> entry : baseline.entrySet())
		{
			int alreadyGained = archived.getOrDefault(entry.getKey(), 0);
			adjusted.put(entry.getKey(), Math.max(0, entry.getValue() - alreadyGained));
		}
		return adjusted;
	}

	/**
	 * Writes the day that just finished into the archive before its baseline is discarded.
	 *
	 * <p>The closing XP is taken from lastKnownXp rather than from live XP. When midnight
	 * passes while logged in the two are the same. When the client was closed over the
	 * boundary, lastKnownXp is the value from the last session, which keeps XP earned after
	 * reopening out of the previous day's total.
	 */
	private void archiveDay(
		TreeMap<String, Map<String, Integer>> history,
		String finishedKey,
		Map<String, Integer> baseline,
		int historyDays)
	{
		if (historyDays <= 0 || finishedKey == null || baseline.isEmpty())
		{
			// Retention off, or a fresh install with no completed day to close out.
			return;
		}

		Map<String, Integer> totals = diff(state.lastKnownXp, baseline);
		if (!totals.isEmpty())
		{
			history.put(finishedKey, totals);
		}

		trim(history, historyDays);
	}

	/**
	 * Applies the retention setting to what is already stored. Called when the setting changes
	 * and on load, so lowering it takes effect immediately instead of at the next rollover.
	 */
	boolean enforceRetention(int historyDays)
	{
		boolean changed = trim(state.historyLocal, historyDays);
		changed |= trim(state.historyUtc, historyDays);
		changed |= trimOffline(state.offlineHistoryLocal, state.historyLocal);
		changed |= trimOffline(state.offlineHistoryUtc, state.historyUtc);
		if (changed)
		{
			dirty = true;
			save();
		}
		return changed;
	}

	/**
	 * Drops offline entries for days the archive no longer holds.
	 *
	 * @return true if anything was removed
	 */
	private static boolean trimOffline(
		TreeMap<String, Map<String, Integer>> offline,
		TreeMap<String, Map<String, Integer>> history)
	{
		if (offline.isEmpty())
		{
			return false;
		}

		if (history.isEmpty())
		{
			offline.clear();
			return true;
		}

		// A view onto the entries older than the archive's oldest day; clearing it removes
		// them from the backing map.
		Map<String, Map<String, Integer>> stale = offline.headMap(history.firstKey(), false);
		if (stale.isEmpty())
		{
			return false;
		}

		stale.clear();
		return true;
	}

	private static boolean trim(TreeMap<String, Map<String, Integer>> history, int keep)
	{
		if (keep <= 0)
		{
			if (history.isEmpty())
			{
				return false;
			}
			history.clear();
			return true;
		}

		boolean changed = false;
		while (history.size() > keep)
		{
			history.remove(history.firstKey());
			changed = true;
		}
		return changed;
	}

	/**
	 * Completed days, newest first, totalled over the current selection. The archive stores
	 * every skill, so this filter is applied at read time and changing the selection re-totals
	 * past days instead of losing them.
	 */
	List<DayTotal> history(TrackingMode mode, Set<String> selection, int limit)
	{
		List<DayTotal> days = new ArrayList<>();
		if (limit <= 0)
		{
			return days;
		}

		TreeMap<String, Map<String, Integer>> source =
			mode == TrackingMode.UTC_DAY ? state.historyUtc : state.historyLocal;

		TreeMap<String, Map<String, Integer>> offlineSource =
			mode == TrackingMode.UTC_DAY ? state.offlineHistoryUtc : state.offlineHistoryLocal;

		for (Map.Entry<String, Map<String, Integer>> entry : source.descendingMap().entrySet())
		{
			if (days.size() >= limit)
			{
				break;
			}

			long total = 0;
			Map<String, Integer> selected = new HashMap<>();
			for (Map.Entry<String, Integer> gain : entry.getValue().entrySet())
			{
				if (selection.contains(gain.getKey()))
				{
					total += gain.getValue();
					selected.put(gain.getKey(), gain.getValue());
				}
			}

			long offline = totalOver(offlineSource.get(entry.getKey()), selection);
			days.add(new DayTotal(entry.getKey(), total, Math.min(offline, total), sortDescending(selected)));
		}

		return days;
	}

	/**
	 * Compares live XP against the last value we saw. Anything positive was earned while the
	 * plugin was not watching: another client, mobile, or a crash we did not flush before.
	 * Returns an empty map for an account we have never seen, so a fresh install does not
	 * report the entire account as a gain.
	 */
	Map<String, Integer> detectOfflineGains(Map<String, Integer> currentXp)
	{
		Map<String, Integer> gained = new HashMap<>();
		for (Map.Entry<String, Integer> entry : currentXp.entrySet())
		{
			Integer previous = state.lastKnownXp.get(entry.getKey());
			if (previous == null)
			{
				continue;
			}

			int delta = entry.getValue() - previous;
			if (delta > 0)
			{
				gained.put(entry.getKey(), delta);
			}
		}
		return gained;
	}

	/**
	 * Records that we are watching the account right now, without marking the state dirty.
	 *
	 * <p>Called every tick so that lastKnownXp stays level with live XP while logged in. That
	 * matters at rollover: archiveDay closes a day out using lastKnownXp, so a stale value
	 * would drop the last few seconds before midnight out of both days. Persistence is left to
	 * the normal flush cycle, since nothing here needs to survive a crash any more urgently
	 * than the XP that produced it.
	 */
	void observe(Map<String, Integer> currentXp, long now)
	{
		state.lastKnownXp.putAll(currentXp);
		state.lastSeenMillis = now;
	}

	void updateLastKnown(Map<String, Integer> currentXp, long now)
	{
		observe(currentXp, now);
		dirty = true;
	}

	/**
	 * Wipes the live windows and starts counting again from now. Archived days are kept:
	 * clearing today's counter should not destroy last week.
	 */
	void reset(Map<String, Integer> currentXp, ZoneId localZone, long now, int historyDays)
	{
		state.buckets.clear();
		state.localDayKey = null;
		state.utcDayKey = null;
		state.localBaseline = new HashMap<>();
		state.utcBaseline = new HashMap<>();
		state.trackingStartedMillis = now;
		state.offlineLocal.clear();
		state.offlineUtc.clear();
		// Baselines are cleared first so the rollover has nothing to archive.
		checkDayRollover(currentXp, localZone, now, historyDays);
		updateLastKnown(currentXp, now);
		dirty = true;
		save();
	}

	XpSnapshot snapshot(
		TrackingMode mode,
		Set<String> selection,
		Map<String, Integer> currentXp,
		ZoneId localZone,
		long now,
		int historyLimit)
	{
		Map<String, Integer> gains;
		switch (mode)
		{
			case ROLLING_24H:
				gains = rollingGains(now);
				break;
			case UTC_DAY:
				gains = diff(currentXp, state.utcBaseline);
				break;
			case LOCAL_DAY:
			default:
				gains = diff(currentXp, state.localBaseline);
				break;
		}

		long overallTotal = 0;
		Map<String, Integer> selected = new HashMap<>();
		for (Map.Entry<String, Integer> entry : gains.entrySet())
		{
			overallTotal += entry.getValue();
			if (selection.contains(entry.getKey()))
			{
				selected.put(entry.getKey(), entry.getValue());
			}
		}

		// XP at the window's start, reconstructed so the UI can derive levels without needing
		// a second source of truth.
		Map<String, Integer> startXp = new HashMap<>();
		for (Map.Entry<String, Integer> entry : selected.entrySet())
		{
			int current = currentXp.getOrDefault(entry.getKey(), 0);
			startXp.put(entry.getKey(), Math.max(0, current - entry.getValue()));
		}

		long windowStart = windowStart(mode, localZone, now);
		boolean partial = state.trackingStartedMillis > windowStart;
		long effectiveStart = Math.max(windowStart, state.trackingStartedMillis);

		// The rolling window has no day boundary to attribute offline XP against, and it
		// already carries it in the buckets at detection time, so it reports none.
		long offlineTotal = 0;
		if (mode != TrackingMode.ROLLING_24H)
		{
			offlineTotal = totalOver(
				mode == TrackingMode.UTC_DAY ? state.offlineUtc : state.offlineLocal, selection);
		}

		return new XpSnapshot(mode, selection, sortDescending(selected), overallTotal, offlineTotal,
			effectiveStart, windowEnd(mode, localZone, now), partial,
			history(mode, selection, historyLimit), startXp);
	}

	private Map<String, Integer> rollingGains(long now)
	{
		long cutoff = (now - WINDOW_MILLIS) / BUCKET_MILLIS;
		Map<String, Integer> totals = new HashMap<>();
		for (Map.Entry<Long, Map<String, Integer>> bucket : state.buckets.tailMap(cutoff, true).entrySet())
		{
			bucket.getValue().forEach((skill, xp) -> totals.merge(skill, xp, Integer::sum));
		}
		return totals;
	}

	private static Map<String, Integer> diff(Map<String, Integer> current, Map<String, Integer> baseline)
	{
		Map<String, Integer> gains = new HashMap<>();
		for (Map.Entry<String, Integer> entry : current.entrySet())
		{
			Integer base = baseline.get(entry.getKey());
			if (base == null)
			{
				continue;
			}

			int delta = entry.getValue() - base;
			if (delta > 0)
			{
				gains.put(entry.getKey(), delta);
			}
		}
		return gains;
	}

	private long windowStart(TrackingMode mode, ZoneId localZone, long now)
	{
		switch (mode)
		{
			case ROLLING_24H:
				return now - WINDOW_MILLIS;
			case UTC_DAY:
				return LocalDate.ofInstant(Instant.ofEpochMilli(now), ZoneOffset.UTC)
					.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
			case LOCAL_DAY:
			default:
				return LocalDate.ofInstant(Instant.ofEpochMilli(now), localZone)
					.atStartOfDay(localZone).toInstant().toEpochMilli();
		}
	}

	/** Midnight at the end of the current day, or 0 for the rolling window. */
	private long windowEnd(TrackingMode mode, ZoneId localZone, long now)
	{
		Instant instant = Instant.ofEpochMilli(now);
		switch (mode)
		{
			case UTC_DAY:
				return LocalDate.ofInstant(instant, ZoneOffset.UTC).plusDays(1)
					.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
			case LOCAL_DAY:
				return LocalDate.ofInstant(instant, localZone).plusDays(1)
					.atStartOfDay(localZone).toInstant().toEpochMilli();
			default:
				return 0;
		}
	}

	/** Whether the goal notification has already fired for this day. */
	boolean goalPending(String dayKey)
	{
		return dayKey != null && !dayKey.equals(state.goalNotifiedDayKey);
	}

	void markGoalNotified(String dayKey)
	{
		state.goalNotifiedDayKey = dayKey;
		dirty = true;
	}

	String currentDayKey(TrackingMode mode)
	{
		return mode == TrackingMode.UTC_DAY ? state.utcDayKey : state.localDayKey;
	}

	private static Map<String, Integer> sortDescending(Map<String, Integer> gains)
	{
		Map<String, Integer> sorted = new LinkedHashMap<>();
		gains.entrySet().stream()
			.sorted(Map.Entry.<String, Integer>comparingByValue(Comparator.reverseOrder()))
			.forEach(e -> sorted.put(e.getKey(), e.getValue()));
		return sorted;
	}

	/** Sums a skill map over the current selection, tolerating a null map. */
	private static long totalOver(Map<String, Integer> gains, Set<String> selection)
	{
		if (gains == null)
		{
			return 0;
		}

		long sum = 0;
		for (Map.Entry<String, Integer> entry : gains.entrySet())
		{
			if (selection.contains(entry.getKey()))
			{
				sum += entry.getValue();
			}
		}
		return sum;
	}

	/**
	 * The baseline a newly entered day starts from: where the previous day left off, not where
	 * live XP happens to be at login. When the client was closed across midnight the two differ
	 * by whatever was earned in the gap, and using live XP silently absorbs it into the baseline
	 * instead of counting it toward a day.
	 */
	private Map<String, Integer> carriedBaseline(Map<String, Integer> currentXp)
	{
		if (state.lastKnownXp.isEmpty())
		{
			return new HashMap<>(currentXp);
		}

		Map<String, Integer> baseline = new HashMap<>();
		for (Map.Entry<String, Integer> entry : currentXp.entrySet())
		{
			Integer known = state.lastKnownXp.get(entry.getKey());
			// Never above current XP; a skill we have not seen before starts from where it is now.
			baseline.put(entry.getKey(), known == null ? entry.getValue() : Math.min(known, entry.getValue()));
		}
		return baseline;
	}
}

